const crypto = require('crypto');
const input = $input.first();
const headers = input.json.headers || {};
const webhookId = String(headers['webhook-id'] || '');
const timestamp = String(headers['webhook-timestamp'] || '');
const signatureHeader = String(headers['webhook-signature'] || '');

function invalid(error, status = 401) {
  return [{ json: { valid: false, duplicate: false, status, error } }];
}

if (!webhookId || !timestamp || !signatureHeader) {
  return invalid('Faltan headers Standard Webhooks.');
}

const timestampNumber = Number(timestamp);
if (!Number.isFinite(timestampNumber) || Math.abs(Date.now() / 1000 - timestampNumber) > 300) {
  return invalid('El timestamp del webhook esta fuera de la ventana permitida.');
}

const rawSecret = String($env.SUPABASE_SEND_EMAIL_HOOK_SECRET || '');
if (!rawSecret) {
  return invalid('SUPABASE_SEND_EMAIL_HOOK_SECRET no esta configurado.', 500);
}

let rawBuffer;
try {
  rawBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (error) {
  const encoded = input.binary?.data?.data;
  if (!encoded) return invalid('n8n no entrego el body crudo.', 500);
  rawBuffer = Buffer.from(encoded, 'base64');
}

const rawBody = rawBuffer.toString('utf8');
const signedContent = `${webhookId}.${timestamp}.${rawBody}`;
const received = signatureHeader.split(' ').map((part) => part.trim()).filter(Boolean);
const secrets = rawSecret.split('|').map((value) => value.trim()).filter(Boolean);
let signatureValid = false;

for (const configuredSecret of secrets) {
  const secret = configuredSecret.replace(/^v1,whsec_/, '').replace(/^whsec_/, '');
  let key;
  try {
    key = Buffer.from(secret, 'base64');
  } catch {
    continue;
  }

  const expected = crypto.createHmac('sha256', key).update(signedContent).digest('base64');
  for (const candidate of received) {
    const parts = candidate.split(',');
    if (parts.length !== 2 || parts[0] !== 'v1') continue;

    const actualBuffer = Buffer.from(parts[1]);
    const expectedBuffer = Buffer.from(expected);
    if (
      actualBuffer.length === expectedBuffer.length &&
      crypto.timingSafeEqual(actualBuffer, expectedBuffer)
    ) {
      signatureValid = true;
      break;
    }
  }

  if (signatureValid) break;
}

if (!signatureValid) return invalid('Firma Standard Webhooks invalida.');

let payload;
try {
  payload = JSON.parse(rawBody);
} catch {
  return invalid('El body no es JSON valido.', 400);
}

const user = payload.user || {};
const emailData = payload.email_data || {};
const actionType = String(emailData.email_action_type || '');
const recipient = String(user.email || '').trim().toLowerCase();
const tokenHash = String(emailData.token_hash || '');

if (!recipient || !tokenHash || !['invite', 'recovery'].includes(actionType)) {
  return invalid('Payload incompleto o email_action_type no soportado.', 422);
}

function safePath(value) {
  return typeof value === 'string' && value.startsWith('/') && !value.startsWith('//')
    ? value
    : null;
}

function queryParam(value, name) {
  const match = String(value || '').match(new RegExp('[?&]' + name + '=([^&#]*)'));
  if (!match) return null;

  try {
    return decodeURIComponent(match[1].replace(/\+/g, ' '));
  } catch {
    return null;
  }
}

function extractOrigin(value) {
  const match = String(value || '').trim().match(/^(https?:\/\/[^/?#]+)/i);
  return match ? match[1].replace(/\/+$/, '') : null;
}

let next = safePath(queryParam(emailData.redirect_to, 'next'));
if (!next) {
  next = recipient.endsWith('@laburuagencia.com')
    ? '/update-password'
    : '/portal/activar';
}

const appOrigin =
  extractOrigin($env.AGENCY_OS_PUBLIC_URL) ||
  extractOrigin(emailData.site_url) ||
  extractOrigin(emailData.redirect_to);

if (!appOrigin) {
  return invalid('No se pudo resolver el dominio de Agency OS.', 422);
}

const confirmUrl =
  `${appOrigin}/auth/confirm` +
  `?token_hash=${encodeURIComponent(tokenHash)}` +
  `&type=${encodeURIComponent(actionType)}` +
  `&next=${encodeURIComponent(next)}`;

function escapeHtml(value) {
  return String(value).replace(
    /[&<>\"']/g,
    (character) =>
      ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '\"': '&quot;',
        "'": '&#039;',
      })[character],
  );
}

const isInvite = actionType === 'invite';
const subject = isInvite
  ? 'Te invitaron a Agency OS'
  : 'Recuperar tu contrasena - Agency OS';
const title = isInvite
  ? 'Te invitaron a Agency OS'
  : 'Recuperar tu contrasena';
const description = isInvite
  ? `Crea tu contrasena para empezar a usar tu cuenta (<span style=\"color:#f6f6f7;\">${escapeHtml(recipient)}</span>). Este enlace es personal y de un solo uso.`
  : `Pediste restablecer la contrasena de <span style=\"color:#f6f6f7;\">${escapeHtml(recipient)}</span>. Haz clic abajo para elegir una nueva. Este enlace es personal, de un solo uso y expira pronto.`;
const buttonText = isInvite ? 'Aceptar invitacion' : 'Restablecer contrasena';
const footer = isInvite
  ? 'Si no esperabas esta invitacion, puedes ignorar este correo. Nadie podra entrar sin usar el enlace.'
  : 'Si no solicitaste este cambio, puedes ignorar este correo. Tu contrasena actual sigue siendo valida.';
const html = `<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-color:#0a0a0b;padding:40px 16px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;\"><tr><td align=\"center\"><table role=\"presentation\" width=\"100%\" style=\"max-width:480px;background-color:#161618;border:1px solid #2a2a2e;border-radius:16px;overflow:hidden;\"><tr><td style=\"padding:32px 32px 0 32px;\"><div style=\"font-size:20px;font-weight:700;letter-spacing:-0.02em;color:#f6f6f7;\">Agency<span style=\"color:#b8ff3c;\">OS</span></div></td></tr><tr><td style=\"padding:28px 32px 8px 32px;\"><h1 style=\"margin:0;font-size:22px;line-height:1.3;font-weight:700;color:#f6f6f7;\">${title}</h1></td></tr><tr><td style=\"padding:0 32px 28px 32px;\"><p style=\"margin:0;font-size:14.5px;line-height:1.6;color:#a1a1aa;\">${description}</p></td></tr><tr><td style=\"padding:0 32px 32px 32px;\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\"><tr><td style=\"border-radius:999px;background-color:#b8ff3c;\"><a href=\"${escapeHtml(confirmUrl)}\" style=\"display:inline-block;padding:13px 28px;font-size:14px;font-weight:700;color:#0d0f08;text-decoration:none;border-radius:999px;\">${buttonText}</a></td></tr></table></td></tr><tr><td style=\"padding:0 32px 32px 32px;border-top:1px solid #2a2a2e;\"><p style=\"margin:20px 0 0 0;font-size:12.5px;line-height:1.6;color:#6b6b73;\">${footer}</p></td></tr></table><p style=\"margin:20px 0 0 0;font-size:11.5px;color:#6b6b73;\">Laburu Agency - Agency OS</p></td></tr></table>`;

const state = $getWorkflowStaticData('global');
state.processedWebhookIds = state.processedWebhookIds || {};
const cutoff = Date.now() - 24 * 60 * 60 * 1000;

for (const [id, processedAt] of Object.entries(state.processedWebhookIds)) {
  if (Number(processedAt) < cutoff) {
    delete state.processedWebhookIds[id];
  }
}

const duplicate = Boolean(state.processedWebhookIds[webhookId]);

return [
  {
    json: {
      valid: true,
      duplicate,
      webhookId,
      to: recipient,
      subject,
      html,
      actionType,
      confirmUrl,
    },
  },
];

const state = $getWorkflowStaticData('global');
state.processedWebhookIds = state.processedWebhookIds || {};
const verified = $('Verificar firma y preparar correo').first().json;
state.processedWebhookIds[verified.webhookId] = Date.now();
return [{ json: { ok: true, actionType: verified.actionType, to: verified.to } }];
